layer.css:
@import url("https://fonts.googleapis.com/css2?family=Zen+Maru+Gothic:wght@400;700&family=Outfit:wght@300;400;600;700&family=JetBrains+Mono:wght@400;500&display=swap");
[data-ryt="pitch"] { color: rgb(176, 184, 200); background-color: rgba(91, 141, 238, 0.2); border-left: 3px solid var(--ryt-accent); border-radius: 0px 10px 10px 0px; font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.75; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(176, 184, 200); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 16px; padding-bottom: 8px; padding-left: 16px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: rgb(176, 184, 200); border-top: 1px solid rgba(91, 141, 238, 0.2); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.35s cubic-bezier(0.25, 0.1, 0.25, 1) }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 40px; font-weight: 700; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="header"] { box-shadow: rgba(91, 141, 238, 0.04) -1px 0px 0px 0px inset }
[data-ryt="nav"] a { color: var(--ryt-header-text); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 15.2px; font-weight: 600; font-style: normal; line-height: 1.8; letter-spacing: 0.3px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="button"] { color: rgb(176, 184, 200); background-color: rgb(26, 35, 56); border-top: 1px solid rgba(91, 141, 238, 0.2); border-right: 1px solid rgba(91, 141, 238, 0.2); border-bottom: 1px solid rgba(91, 141, 238, 0.2); border-left: 1px solid rgba(91, 141, 238, 0.2); border-radius: 50%; box-shadow: rgba(0, 0, 0, 0.1) 0px 1px 4px 0px; font-family: Arial; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(176, 184, 200); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: opacity 0.2s, left 0.35s cubic-bezier(0.25, 0.1, 0.25, 1), color 0.2s, border-color 0.2s, box-shadow 0.2s }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 38.4px; font-weight: 700; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 600; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.35s cubic-bezier(0.25, 0.1, 0.25, 1); position: relative }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 21.6px; font-weight: 600; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a::after { content: ""; display: block; position: absolute; width: 100%; height: 248.312px; color: var(--ryt-text); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 21.6px; font-weight: 600; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text); top: 0px; left: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #e8609e; color: #4a7de0 }
[data-ryt="button"]:hover { color: #4a7de0; box-shadow: 0 0 12px rgba(91, 141, 238, 0.2); opacity: 1 }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #e8609e }
